842	bool KeyCondition::tryPrepareSetIndex(
843	    const ASTs & args,
844	    ContextPtr context,
845	    RPNElement & out,
846	    size_t & out_key_column_num)
847	{
848	    const ASTPtr & left_arg = args[0];
849	
850	    out_key_column_num = 0;
851	    std::vector<MergeTreeSetIndex::KeyTuplePositionMapping> indexes_mapping;
852	    DataTypes data_types;
853	
854	    auto get_key_tuple_position_mapping = [&](const ASTPtr & node, size_t tuple_index)
855	    {
856	        MergeTreeSetIndex::KeyTuplePositionMapping index_mapping;
857	        index_mapping.tuple_index = tuple_index;
858	        DataTypePtr data_type;
859	        if (isKeyPossiblyWrappedByMonotonicFunctions(
860	                node, context, index_mapping.key_index, data_type, index_mapping.functions))
861	        {
862	            indexes_mapping.push_back(index_mapping);
863	            data_types.push_back(data_type);
864	            if (out_key_column_num < index_mapping.key_index)
865	                out_key_column_num = index_mapping.key_index;
866	        }
867	    };
868	
869	    size_t left_args_count = 1;
870	    const auto * left_arg_tuple = left_arg->as<ASTFunction>();
871	    if (left_arg_tuple && left_arg_tuple->name == "tuple")
872	    {
873	        const auto & tuple_elements = left_arg_tuple->arguments->children;
874	        left_args_count = tuple_elements.size();
875	        for (size_t i = 0; i < left_args_count; ++i)
876	            get_key_tuple_position_mapping(tuple_elements[i], i);
877	    }
878	    else
879	        get_key_tuple_position_mapping(left_arg, 0);
880	
881	    if (indexes_mapping.empty())
882	        return false;
883	
884	    const ASTPtr & right_arg = args[1];
885	
886	    SetPtr prepared_set;
887	    if (right_arg->as<ASTSubquery>() || right_arg->as<ASTTableIdentifier>())
888	    {
889	        auto set_it = prepared_sets.find(PreparedSetKey::forSubquery(*right_arg));
890	        if (set_it == prepared_sets.end())
891	            return false;
892	
893	        prepared_set = set_it->second;
894	    }
895	    else
896	    {
897	        /// We have `PreparedSetKey::forLiteral` but it is useless here as we don't have enough information
898	        /// about types in left argument of the IN operator. Instead, we manually iterate through all the sets
899	        /// and find the one for the right arg based on the AST structure (getTreeHash), after that we check
900	        /// that the types it was prepared with are compatible with the types of the primary key.
901	        auto set_ast_hash = right_arg->getTreeHash();
902	        auto set_it = std::find_if(
903	            prepared_sets.begin(), prepared_sets.end(),
904	            [&](const auto & candidate_entry)
905	            {
906	                if (candidate_entry.first.ast_hash != set_ast_hash)
907	                    return false;
908	
909	                for (size_t i = 0; i < indexes_mapping.size(); ++i)
910	                    if (!candidate_entry.second->areTypesEqual(indexes_mapping[i].tuple_index, data_types[i]))
911	                        return false;
912	
913	                return true;
914	        });
915	        if (set_it == prepared_sets.end())
916	            return false;
917	
918	        prepared_set = set_it->second;
919	    }
920	
921	    /// The index can be prepared if the elements of the set were saved in advance.
922	    if (!prepared_set->hasExplicitSetElements())
923	        return false;
924	
925	    prepared_set->checkColumnsNumber(left_args_count);
926	    for (size_t i = 0; i < indexes_mapping.size(); ++i)
927	        prepared_set->checkTypesEqual(indexes_mapping[i].tuple_index, data_types[i]);
928	
929	    out.set_index = std::make_shared<MergeTreeSetIndex>(prepared_set->getSetElements(), std::move(indexes_mapping));
930	
931	    return true;
932	}
