935	/** Allow to use two argument function with constant argument to be analyzed as a single argument function.
936	  * In other words, it performs "currying" (binding of arguments).
937	  * This is needed, for example, to support correct analysis of `toDate(time, 'UTC')`.
938	  */
939	class FunctionWithOptionalConstArg : public IFunctionBase
940	{
941	public:
942	    enum Kind
943	    {
944	        NO_CONST = 0,
945	        LEFT_CONST,
946	        RIGHT_CONST,
947	    };
948	
949	    explicit FunctionWithOptionalConstArg(const FunctionBasePtr & func_) : func(func_) {}
950	    FunctionWithOptionalConstArg(const FunctionBasePtr & func_, const ColumnWithTypeAndName & const_arg_, Kind kind_)
951	        : func(func_), const_arg(const_arg_), kind(kind_)
952	    {
953	    }
954	
955	    String getName() const override { return func->getName(); }
956	
957	    const DataTypes & getArgumentTypes() const override { return func->getArgumentTypes(); }
958	
959	    const DataTypePtr & getResultType() const override { return func->getResultType(); }
960	
961	    ExecutableFunctionPtr prepare(const ColumnsWithTypeAndName & arguments) const override { return func->prepare(arguments); }
962	
963	    ColumnPtr
964	    execute(const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type, size_t input_rows_count, bool dry_run) const override
965	    {
966	        if (kind == Kind::LEFT_CONST)
967	        {
968	            ColumnsWithTypeAndName new_arguments;
969	            new_arguments.reserve(arguments.size() + 1);
970	            new_arguments.push_back(const_arg);
971	            for (const auto & arg : arguments)
972	                new_arguments.push_back(arg);
973	            return func->prepare(new_arguments)->execute(new_arguments, result_type, input_rows_count, dry_run);
974	        }
975	        else if (kind == Kind::RIGHT_CONST)
976	        {
977	            auto new_arguments = arguments;
978	            new_arguments.push_back(const_arg);
979	            return func->prepare(new_arguments)->execute(new_arguments, result_type, input_rows_count, dry_run);
980	        }
981	        else
982	            return func->prepare(arguments)->execute(arguments, result_type, input_rows_count, dry_run);
983	    }
984	
985	    bool isDeterministic() const override { return func->isDeterministic(); }
986	
987	    bool isDeterministicInScopeOfQuery() const override { return func->isDeterministicInScopeOfQuery(); }
988	
989	    bool hasInformationAboutMonotonicity() const override { return func->hasInformationAboutMonotonicity(); }
990	
991	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & arguments) const override { return func->isSuitableForShortCircuitArgumentsExecution(arguments); }
992	
993	    IFunctionBase::Monotonicity getMonotonicityForRange(const IDataType & type, const Field & left, const Field & right) const override
994	    {
995	        return func->getMonotonicityForRange(type, left, right);
996	    }
997	
998	    Kind getKind() const { return kind; }
999	    const ColumnWithTypeAndName & getConstArg() const { return const_arg; }
1000	
1001	private:
1002	    FunctionBasePtr func;
1003	    ColumnWithTypeAndName const_arg;
1004	    Kind kind = Kind::NO_CONST;
1005	};
