16	/// Builds reverse polish notation
17	template <typename RPNElement>
18	class RPNBuilder : WithContext
19	{
20	public:
21	    using RPN = std::vector<RPNElement>;
22	    using AtomFromASTFunc = std::function<
23	            bool(const ASTPtr & node, ContextPtr context, Block & block_with_constants, RPNElement & out)>;
24	
25	    RPNBuilder(const SelectQueryInfo & query_info, ContextPtr context_, const AtomFromASTFunc & atom_from_ast_)
26	        : WithContext(context_), atom_from_ast(atom_from_ast_)
27	    {
28	        /** Evaluation of expressions that depend only on constants.
29	          * For the index to be used, if it is written, for example `WHERE Date = toDate(now())`.
30	          */
31	        block_with_constants = KeyCondition::getBlockWithConstants(query_info.query, query_info.syntax_analyzer_result, getContext());
32	
33	        /// Transform WHERE section to Reverse Polish notation
34	        const ASTSelectQuery & select = typeid_cast<const ASTSelectQuery &>(*query_info.query);
35	        if (select.where())
36	        {
37	            traverseAST(select.where());
38	
39	            if (select.prewhere())
40	            {
41	                traverseAST(select.prewhere());
42	                rpn.emplace_back(RPNElement::FUNCTION_AND);
43	            }
44	        }
45	        else if (select.prewhere())
46	        {
47	            traverseAST(select.prewhere());
48	        }
49	        else
50	        {
51	            rpn.emplace_back(RPNElement::FUNCTION_UNKNOWN);
52	        }
53	    }
54	
55	    RPN && extractRPN() { return std::move(rpn); }
56	
57	private:
58	    void traverseAST(const ASTPtr & node)
59	    {
60	        RPNElement element;
61	
62	        if (ASTFunction * func = typeid_cast<ASTFunction *>(&*node))
63	        {
64	            if (operatorFromAST(func, element))
65	            {
66	                auto & args = typeid_cast<ASTExpressionList &>(*func->arguments).children;
67	                for (size_t i = 0, size = args.size(); i < size; ++i)
68	                {
69	                    traverseAST(args[i]);
70	
71	                    /** The first part of the condition is for the correct support of `and` and `or` functions of arbitrary arity
72	                      * - in this case `n - 1` elements are added (where `n` is the number of arguments).
73	                      */
74	                    if (i != 0 || element.function == RPNElement::FUNCTION_NOT)
75	                        rpn.emplace_back(std::move(element));
76	                }
77	
78	                return;
79	            }
80	        }
81	
82	        if (!atom_from_ast(node, getContext(), block_with_constants, element))
83	        {
84	            element.function = RPNElement::FUNCTION_UNKNOWN;
85	        }
86	
87	        rpn.emplace_back(std::move(element));
88	    }
89	
90	    bool operatorFromAST(const ASTFunction * func, RPNElement & out)
91	    {
92	        /// Functions AND, OR, NOT.
93	        /// Also a special function `indexHint` - works as if instead of calling a function there are just parentheses
94	        /// (or, the same thing - calling the function `and` from one argument).
95	        const ASTs & args = typeid_cast<const ASTExpressionList &>(*func->arguments).children;
96	
97	        if (func->name == "not")
98	        {
99	            if (args.size() != 1)
100	                return false;
101	
102	            out.function = RPNElement::FUNCTION_NOT;
103	        }
104	        else
105	        {
106	            if (func->name == "and" || func->name == "indexHint")
107	                out.function = RPNElement::FUNCTION_AND;
108	            else if (func->name == "or")
109	                out.function = RPNElement::FUNCTION_OR;
110	            else
111	                return false;
112	        }
113	
114	        return true;
115	    }
116	
117	    const AtomFromASTFunc & atom_from_ast;
118	    Block block_with_constants;
119	    RPN rpn;
120	};
